% conclusion.tex

\section{Discussion}
\label{sec:discussion}

\paragraph{Discriminative compression and label equivalence.}
Three observations argue against a topic shortcut: unstable topic OOD (F1\,=\,0.541$\pm$0.207), scrambled labels within 3.9\,pp, and label-free MLM detection (F1\,$\geq$\,0.97).
Classification DAPT compresses features into few dimensions (participation ratio 3.7--9.4 vs.\ 25--32; Figure~\ref{fig:svd_subspace}; Appendices~\ref{app:representation}--\ref{app:tsne}), concentrated in 3 SVD dimensions in layers 8--12 \citep{zhang2021understanding}; CKA analysis confirms this compression emerges in middle-to-late layers (Appendices~\ref{sec:cka_heatmap},~\ref{app:layerwise}). A probe confirms sufficiency, and removal degrades DD by 17\,pp (Appendices~\ref{app:discriminative_probe},~\ref{app:svd_necessity}).

\paragraph{Cross-condition transfer and boundaries.}
ToxicChat (+18--42\,pp) and cross-LLM experiments (Appendix~\ref{app:cross_llm}) confirm transfer beyond single-LLM artifacts; scale validation on larger training sets preserves the hierarchy (Appendix~\ref{app:scale_validation}). On single-turn human-authored data the hierarchy reverses (MLM leads; Appendix~\ref{app:confidence}); truncated analysis localizes the reversal to distributional gap rather than detection mechanism (Appendix~\ref{app:truncated}). Mixed-LLM 9-class maintains 0.818 while MLM collapses; at 355M, DAPT becomes counterproductive (vanilla AA\,=\,1.000 vs.\ 9-class 0.946). WildChat FPR reaches 68.1\% (synthetic-to-real shift). Length-matched evaluation ($N$=155) shows negligible DD change ($\Delta$\,=\,$-$2.5\,pp; Appendices~\ref{app:length_independence},~\ref{app:length}); ActorAttack padding collapse ($-$57.9\,pp) reflects signal dilution (Appendix~\ref{app:truncated}).

\begin{figure}[t]
\centering
\includegraphics[width=\columnwidth]{figures/paper/fig4_svd_subspace.pdf}
\caption{Test representations projected onto top-2 SVD directions. 9-class DAPT produces clear cluster separation absent in vanilla.}
\label{fig:svd_subspace}
\end{figure}

\paragraph{Deployment implications.}
Our findings suggest a capacity-aware deployment strategy. At base scale (125--184M), any domain-relevant classification objective recovers OOD detection: scrambled labels perform equivalently on template attacks, so practitioners need not invest in annotation quality for this regime. When facing strategy-diverse attacks (e.g., ActorAttack), the label effect resurfaces ($d$\,=\,0.44), favoring semantically meaningful taxonomies. At sufficient capacity ($\geq$355M), DAPT becomes unnecessary and potentially counterproductive; the decision to adapt should be conditioned on encoder scale. Independent of adaptation choice, few-shot benign calibration (10--25 conversations per deployment domain) resolves false-positive rates without requiring target-domain attack data (calibration curves in Appendix~\ref{app:calibration}), enabling deployment across platforms with minimal data collection. The 184M-parameter pipeline maintains 24.3$\times$ inference speedup over LLM-as-judge alternatives (43$\times$ fewer parameters; Appendix~\ref{app:efficiency}), making it suitable for real-time monitoring at scale.

\section{Conclusion}

Classification DAPT recovers OOD detection at base scale (F1\,=\,0.97--1.0 vs.\ vanilla 0.26--0.31), though not under mixed-LLM training on diverse attacks (ActorAttack F1\,=\,0.504); on single-turn human-authored data, the hierarchy reverses (ToxicChat MLM 0.837 vs.\ classification 0.596), making these advantages condition-specific and counterproductive at 355M. Few-shot adaptation reduces FPR from 58--68\% to 0--1.5\%; this ablation framework provides a template for future controlled studies of domain adaptation in safety-critical natural language processing (NLP) tasks.

\section*{Limitations}
\label{sec:limitations}

\begin{itemize}[nosep,leftmargin=*]
\item \textbf{Synthetic data.} All findings derive from synthetic conversations (single LLM, Qwen3-8B; 350 training, 3 seeds); the hierarchy reverses on human single-turn data (ToxicChat), and no human-generated multi-turn jailbreak dataset exists.
\item \textbf{IID benign assumption.} OOD F1 assumes IID benign data; few-shot adaptation recovers performance but is validated on only two platforms ($n \leq 50$).
\item \textbf{Scope.} Only persuasion-mediated multi-turn attacks at base-to-large scale (125--355M); single-turn token-level attacks and non-text modalities are not addressed.
\end{itemize}

% abstract.tex
\begin{abstract}
Multi-turn jailbreaks spread adversarial intent across innocent-looking conversation turns, and safety classifiers designed for single-turn threats miss them: Llama Guard~3 catches only 1.8\%. What makes a detector generalize to attack strategies never seen during training? We introduce DisPeD (Disentangled Persuasion Detection), a controlled framework where seven encoder variants differ solely in pretraining objective while sharing the same frozen classifier; this design isolates how domain exposure, supervision type, and label semantics each contribute to out-of-distribution robustness. Classification-based domain adaptation is the only consistently effective mechanism on synthetic multi-turn attacks: it recovers near-perfect detection where vanilla encoders collapse (F1 0.97--1.0 vs.\ 0.26--0.31) and remains robust under mixed-LLM training where unsupervised pretraining fails entirely. Scrambled labels match correct ones---the classification objective's structural role, not label content, drives generalization. Yet these advantages reverse on human-authored data, where unsupervised pretraining leads, an asymmetry that bounds the scope of each mechanism. The resulting 184M-parameter pipeline achieves 24$\times$ speedup over LLM-as-judge alternatives, and few-shot adaptation substantially reduces false-positive inflation across deployment platforms\footnote{Code and data are available at \url{https://anonymous.4open.science/r/persuasion_turn_jailbreak_detect-C207/}.}.
\end{abstract}

% introduction.tex

\section{Introduction}

Multi-turn jailbreak attacks distribute adversarial intent across individually benign turns. Crescendo~\citep{russinovich2024crescendo}, Foot-in-the-Door~\citep{fitd2024}, and Deceptive Delight~\citep{deceptivedelight2024} all rely on persuasion as their core mechanism: \citet{zeng2024pap} catalogue 40 persuasion techniques across jailbreak families, and \citet{hagendorff2026reasoning} identify strategies in 97\% of successful attacks. Because individual attack turns occupy the same embedding region as benign text~\citep{bullwinkel2025repeng}, no single-turn filter can distinguish them from legitimate conversation.

Existing defenses leave a critical gap. Production classifiers such as Llama Guard~\citep{inan2023llamaguard}, WildGuard~\citep{han2024wildguard}, and ShieldGemma~\citep{zeng2024shieldgemma} operate on individual turns and miss multi-turn manipulation; Llama Guard~3 detects only 1.8\% of multi-turn jailbreaks in our evaluation (Section~\ref{sec:decomposition}). Multi-turn defenses (DeepContext~\citep{deepcontext2026}, BIID~\citep{tong2025biid}, G-Guard~\citep{gguard2025}) model conversation-level structure but each evaluates on a single attack family. None answers the central question: \emph{what representation properties enable a detector to generalize across attack families it has never seen?} Pretrained language understanding alone does not suffice: vanilla DeBERTa-v3~\citep{he2023debertav3} with temporal aggregation (cf.\ DeepContext~\citep{deepcontext2026}) drops from F1\,=\,1.000 in-distribution to 0.312 on OOD Deceptive Delight, and GPT-5.5 reaches only 0.191--0.449 F1 (across prefix lengths) with 30--47\% unparseable responses (Appendix~\ref{sec:llm_judge}). The bottleneck is distributional: cross-attack generalization at base model scale benefits substantially from domain adaptation.

\begin{figure*}[t]
\centering
\includegraphics[width=\textwidth]{figures/paper/fig1_architecture.pdf}
\caption{DisPeD architecture. Stage~1 adapts a DeBERTa encoder on jailbreak conversation text (seven variant objectives). Stage~2 aggregates frozen \texttt{[CLS]} embeddings via BiGRU for conversation-level jailbreak detection. Only user turns are processed.}
\label{fig:architecture}
\end{figure*}

Our pipeline, \textbf{DisPeD} (Disentangled Persuasion Detection)\footnote{We use `disentangled' to describe our experimental methodology of isolating individual factors through controlled ablation, distinct from disentangled representation learning ($\beta$-VAE, InfoGAN).}, separates encoder adaptation (Stage~1) from temporal classification (Stage~2, a frozen BiGRU; Figure~\ref{fig:architecture}). Seven Stage~1 variants each isolate a single factor while holding all others constant (Section~\ref{sec:method}); the contribution is the decomposition, not the pipeline. Controlled ablation across DeBERTa-v3 and RoBERTa~\citep{liu2019roberta} on four attack families reveals three findings at base model scale: classification-based domain-adaptive pretraining (DAPT) is the only variant that consistently recovers OOD detection (F1\,=\,0.97--1.0 vs.\ vanilla 0.26--0.31), even under mixed-LLM training where unsupervised pretraining collapses to vanilla level~\citep{gururangan2020dontstop}; scrambled labels match correct labels for template attacks, which shows that the classification objective's structural role, not label semantics, drives generalization; yet this hierarchy reverses entirely on human-authored data (MLM 0.837 vs.\ classification 0.596), revealing condition-specific rather than universal advantages. At 355M parameters, capacity alone suffices: RoBERTa-large handles ActorAttack~\citep{ren2024actorattack} without adaptation.

Our contributions:
\begin{itemize}[leftmargin=*, itemsep=2pt, topsep=4pt]
  \item \textbf{Systematic ablation of cross-attack generalization.} Thirteen encoder configurations at three scales (125--355M) decompose jailbreak detection into attack-side and benign-side factors, constituting, to the best of our knowledge, the first controlled factorial study in this domain. Classification DAPT recovers OOD detection (0.26--0.31 $\rightarrow$ 0.97--1.0) while unsupervised pretraining collapses under mixed-LLM training; 10--25 benign conversations reduce false-positive rates (FPR) from 58--68\% to 0--1.5\%.

  \item \textbf{Partition sufficiency with a difficulty gradient.} Scrambled labels match correct labels for template-attack detection (Two One-Sided Tests [TOST] $|d| \leq 0.14$), but strategy-diverse attacks retain moderate label sensitivity ($d$\,=\,0.44). Domain-relevant partitioning, not label semantics, is the operative mechanism, consistent with \citet{zhang2021understanding}: compression localizes to 3 singular value decomposition (SVD) dimensions in layers 8--12.

  \item \textbf{Practical adaptation protocol.} A 184M-parameter encoder achieves 24.3$\times$ speedup over LLM-as-judge (43$\times$ fewer parameters; Appendix~\ref{app:efficiency}); few-shot benign adaptation resolves deployment-blocking FPR without target-domain attack data.
\end{itemize}

% experiments.tex

\section{Experiments}

\begin{figure}[t]
\centering
\includegraphics[width=\columnwidth]{figures/paper/fig3_evidence_hierarchy.pdf}
\caption{Evidence hierarchy across evaluation conditions. Classification-based DAPT outperforms MLM and vanilla on synthetic OOD attacks (DD, AA), but the hierarchy reverses on human-authored single-turn data (ToxicChat), where JB-MLM leads.}
\label{fig:evidence_hierarchy}
\end{figure}

